={{ (() => {
  const s = $json.slack || {};
  const texto = s.texto || 'Sesión en vivo';
  const m = texto.match(/<(https?:\/\/[^>|]+)/);
  const url = (m && m[1]) || 'https://portal.modofundraising.com/portal/clases';
  return JSON.stringify({
    channel: s.canal || '#modo-fundraising',
    text: texto,
    blocks: [
      { type: 'section', text: { type: 'mrkdwn', text: texto } },
      { type: 'actions', elements: [
        { type: 'button', text: { type: 'plain_text', text: '🔴 Entrar al vivo', emoji: true }, url, style: 'primary', action_id: 'entrar_vivo' }
      ] }
    ]
  });
})() }}

